function AdBanner({slot='REPLACE_WITH_AD_SLOT', className=''}) {
  const client = import.meta.env.VITE_ADSENSE_CLIENT || ''
  const enabled = Boolean(client && slot && slot !== 'REPLACE_WITH_AD_SLOT')
  useEffect(() => {
    if (!enabled) return
    if (!document.querySelector('script[data-adsense="true"]')) {
      const s=document.createElement('script'); s.async=true; s.crossOrigin='anonymous'; s.dataset.adsense='true'
      s.src=`https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${client}`
      document.head.appendChild(s)
    }
    try { (window.adsbygoogle=window.adsbygoogle||[]).push({}) } catch {}
  }, [enabled,client,slot])
  if (!enabled) return null
  return <div className={`ad-wrap ${className}`} aria-label="Advertisement"><span>Advertisement</span><ins className="adsbygoogle" style={{display:'block',minHeight:90}} data-ad-client={client} data-ad-slot={slot} data-ad-format="auto" data-full-width-responsive="true"/></div>
}
